<script setup lang="ts">
import {nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
type Row=Record<string,any>;
const props=defineProps<{groups:{name:string,items:any[][]}[],user:Row,page:string,disabled:boolean,admin:boolean}>();
const emit=defineEmits<{navigate:[page:string],logout:[],change:[state:{narrow:boolean,open:boolean,collapsed:boolean}],restoreFocus:[]}>();
function saved(){try{return localStorage.getItem('starhub.portal.nav-collapsed')==='1'}catch{return false}}
const collapsed=ref(saved()),open=ref(false),narrow=ref(false),groupsOpen=ref<string[]>([]),aside=ref<HTMLElement>(),closeButton=ref<HTMLButtonElement>();
let query:MediaQueryList|undefined,previousOverflow:string|undefined;
function expanded(g:{name:string,items:any[][]}){return !props.admin||g.name==='工作台'||groupsOpen.value.includes(g.name)||g.items.some(t=>t[0]===props.page)}
function close(){if(open.value){open.value=false;emit('restoreFocus')}}
function toggle(){if(narrow.value)open.value=!open.value;else{collapsed.value=!collapsed.value;if(collapsed.value)emit('restoreFocus');try{localStorage.setItem('starhub.portal.nav-collapsed',collapsed.value?'1':'0')}catch{}}}
function select(page:string){emit('navigate',page);close()}
function changed(){narrow.value=!!query?.matches;open.value=false}
function escape(e:KeyboardEvent){if(e.key==='Escape'&&open.value)close()}
function trap(e:KeyboardEvent){if(e.key!=='Tab'||!narrow.value||!open.value)return;const items=aside.value?.querySelectorAll<HTMLElement>('a[href],button:not([disabled])');if(!items?.length)return;const visible=Array.from(items).filter(x=>x.getClientRects().length),first=visible[0],last=visible.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
watch([narrow,open,collapsed],async()=>{emit('change',{narrow:narrow.value,open:open.value,collapsed:collapsed.value});if(narrow.value&&open.value){if(previousOverflow===undefined){previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden'}await nextTick();closeButton.value?.focus()}else if(previousOverflow!==undefined){document.body.style.overflow=previousOverflow;previousOverflow=undefined}},{immediate:true});
onMounted(()=>{query=window.matchMedia?.('(max-width: 760px)');changed();query?.addEventListener('change',changed);document.addEventListener('keydown',escape)});
onBeforeUnmount(()=>{query?.removeEventListener('change',changed);document.removeEventListener('keydown',escape);if(previousOverflow!==undefined)document.body.style.overflow=previousOverflow});
defineExpose({toggle});
</script>
<template><button v-if="narrow&&open" class="nav-backdrop" aria-label="关闭导航遮罩" @click="close"></button><aside id="workspace-navigation" ref="aside" class="sidebar workspace-sidebar" :class="{'drawer-open':narrow&&open,'desktop-hidden':!narrow&&collapsed}" :inert="narrow?!open:collapsed" :role="narrow&&open?'dialog':undefined" :aria-modal="narrow&&open?true:undefined" aria-label="功能导航" @keydown="trap"><div class="sidebar-brand"><a class="brand" href="/">✦ <span>STARHUB <small>{{admin?'运营管理台':'我的用户中心'}}</small></span></a><button ref="closeButton" class="nav-close" :aria-label="narrow?'关闭导航':'收起侧栏'" @click="narrow?close():toggle()">{{narrow?'×':'‹'}}</button></div><div class="nav-caption">{{admin?'WORKSPACE · 运营工作区':'MY ACCOUNT · 我的账户'}}</div><nav><div v-for="group in groups" :key="group.name" class="nav-group"><button v-if="admin" class="nav-group-title" :aria-expanded="expanded(group)" @click="groupsOpen=groupsOpen.includes(group.name)?groupsOpen.filter(n=>n!==group.name):[...groupsOpen,group.name]">{{group.name}} <span>⌄</span></button><div class="nav-group-items" :class="{collapsed:!expanded(group)}"><button v-for="t in group.items" :key="t[0]" :disabled="disabled" @click="select(t[0])" :class="{selected:page===t[0]}" :aria-current="page===t[0]?'page':undefined"><span>{{t[2]}}</span>{{t[1]}}</button></div></div></nav><div class="account"><div class="avatar">{{user.name.slice(0,1)}}</div><div><strong>{{user.name}}</strong><small>{{admin?(user.is_owner?'主管理员':'副管理员'):'购买用户'}}</small></div><button @click="emit('logout')" title="退出登录">↗</button></div></aside></template>
<style scoped>
.sidebar-brand{display:flex;align-items:center;gap:4px}.sidebar-brand .brand{margin-right:0;flex:1;min-width:0}.sidebar-brand .brand>span{font-size:15px}.sidebar-brand .nav-close{flex:none;width:30px;height:34px;padding:0;background:transparent;border-color:#405169;color:#c3d0df;font-size:22px}.workspace-sidebar.desktop-hidden{transform:translateX(-100%);visibility:hidden;pointer-events:none}.nav-backdrop{position:fixed;inset:0;z-index:100;background:#0b162bb3;border:0;border-radius:0;padding:0}.workspace-sidebar{transition:transform .18s ease}
@media(max-width:760px){.portal-app .workspace-sidebar{position:fixed;inset:0 auto 0 0;z-index:110;width:min(300px,calc(100vw - 48px));height:100dvh;padding:20px 14px;display:flex;flex-direction:column;transform:translateX(-100%);visibility:hidden;box-shadow:10px 0 35px #07101e40}.portal-app .workspace-sidebar.drawer-open{transform:translateX(0);visibility:visible}.portal-app .workspace-sidebar nav{display:block;overflow-x:hidden;overflow-y:auto;align-items:initial;flex:1}.portal-app .workspace-sidebar .nav-group{display:block;margin-bottom:10px}.portal-app .workspace-sidebar .nav-group-items{display:block}.portal-app .workspace-sidebar .nav-group-items.collapsed{display:none}.portal-app .workspace-sidebar button.nav-group-title{display:flex;width:100%;font-size:11px;padding:10px}.portal-app .workspace-sidebar .nav-group-items>button{display:flex;width:100%;min-height:44px;font-size:13px;justify-content:flex-start;margin:3px 0}.portal-app .workspace-sidebar .sidebar-brand{margin-bottom:14px}.portal-app .workspace-sidebar .brand{margin:0;font-size:28px}.portal-app .workspace-sidebar .brand small{display:block;padding:3px 0;font-size:9px}.portal-app .workspace-sidebar .nav-caption{display:block;font-size:9px;margin:0 10px 10px}.portal-app .workspace-sidebar .account{position:static;display:flex;align-items:center;padding:15px 5px 0;margin-top:12px;border-top:1px solid #304053;gap:10px}.portal-app .workspace-sidebar .account>div{display:block}.portal-app .workspace-sidebar .account .avatar{display:grid}.portal-app .workspace-sidebar .account button{margin-left:auto}.portal-app .workspace-sidebar .sidebar-brand .nav-close{width:40px;height:40px}}
</style>
